INSERT INTO specialized_permission_policies (
    policy_id, policy_code, policy_version, action_code, policy_name,
    policy_type, scope_type, scope_id, rule_config, required_approval_level,
    fail_closed, lifecycle_status, valid_from, valid_until, created_by_principal_id
) VALUES (
    #{policyId}, #{policyCode}, #{policyVersion}, #{actionCode}, #{policyName},
    #{policyType}, #{scopeType}, #{scopeId}, #{ruleConfig}::jsonb, #{requiredApprovalLevel},
    #{failClosed}, #{lifecycleStatus}, COALESCE(#{validFrom}, CURRENT_TIMESTAMP), #{validUntil}, #{createdByPrincipalId}
)

mapper.select:
SELECT *
FROM specialized_permission_policies
WHERE action_code = #{actionCode}
  AND lifecycle_status = 'ACTIVE'
  AND scope_type = #{scopeType}
  AND (
    (#{scopeId} IS NULL AND scope_id IS NULL)
    OR scope_id = #{scopeId}
  )
  AND valid_from <= CURRENT_TIMESTAMP
  AND (valid_until IS NULL OR valid_until > CURRENT_TIMESTAMP)
ORDER BY policy_version DESC
LIMIT 1
